from dataclasses import dataclass

SURVIVAL_NEIGHBOR_COUNTS = (2, 3)


@dataclass(frozen=True)
class Cell:
    x: int
    y: int


def next_generation(living_cells):
    return [
        cell for cell in _candidate_cells(living_cells) if _survives(cell, living_cells)
    ]


def _candidate_cells(living_cells):
    return living_cells


def _survives(cell, living_cells):
    return _living_neighbor_count(cell, living_cells) in SURVIVAL_NEIGHBOR_COUNTS


def _living_neighbor_count(cell, living_cells):
    return sum(1 for other in living_cells if _are_neighbors(cell, other))


def _are_neighbors(cell, other):
    return cell != other and abs(cell.x - other.x) <= 1 and abs(cell.y - other.y) <= 1
